import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 3

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'clinical':  # Skip clinical for simplicity
            t_stat = feats.x[:, i].T @ feats.y / np.sqrt(np.var(feats.x[:, i]) * np.mean(feats.y) * (1 - np.mean(feats.y)))
            p_val = 2 * (1 - stats.t.cdf(abs(t_stat), feats.n - 1))
            if p_val < 0.05:
                sig_features.append((fid, i, p_val))

    # Sort by significance
    sig_features.sort(key=lambda x: x[2])

    # Check for product terms between top features
    candidates = [f[0] for f in sig_features[:10]]  # Top 10 features

    # Remove near-duplicates based on correlation
    to_remove = set()
    for i in range(len(candidates)):
        for j in range(i+1, len(candidates)):
            fid1, fid2 = candidates[i], candidates[j]
            col1, col2 = feats.column(fid1), feats.column(fid2)
            corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0, 1]
            if abs(corr) >= 0.6:
                to_remove.add(fid2)

    candidates = [f for f in candidates if f not in to_remove]

    # Try product terms
    best_score = -np.inf
    best_product = None

    for i in range(len(candidates)):
        for j in range(i+1, len(candidates)):
            fid1, fid2 = candidates[i], candidates[j]
            col1, col2 = feats.column(fid1), feats.column(fid2)

            # Create product feature
            prod = feats.x[:, col1] * feats.x[:, col2]

            # Test logistic regression with product term
            X = np.column_stack([feats.x[:, col1], feats.x[:, col2], prod])
            clf = LogisticRegression(penalty='l2', C=1e6, fit_intercept=True, max_iter=1000)
            clf.fit(X, feats.y)

            # Use log-likelihood as score
            y_pred_proba = clf.predict_proba(X)[:, 1]
            score = np.sum(feats.y * np.log(y_pred_proba + 1e-10) + (1 - feats.y) * np.log(1 - y_pred_proba + 1e-10))

            if score > best_score:
                best_score = score
                best_product = (fid1, fid2)

    if best_product:
        return Design(
            drivers=(best_product[0], best_product[1]),
            columns=(best_product[0], best_product[1]),
            products=(best_product,),
            loadings={}
        )
    elif len(sig_features) > 0:
        # Return strongest single feature
        return Design(
            drivers=(sig_features[0][0],),
            columns=(sig_features[0][0],),
            products=(),
            loadings={}
        )
    else:
        # No mechanism found
        return Design(
            drivers=(),
            columns=(),
            products=(),
            loadings={}
        )

